type Reading = {
    station: string;
    strength: number;
};

function strongest(readings: Reading[]): Reading | undefined {
    return readings.reduce<Reading | undefined>((best, reading) => {
        if (!best || reading.strength > best.strength) {
            return reading;
        }
        return best;
    }, undefined);
}

interface ArchiveEntry {
    name: string;
    active: boolean;
}

function activeNames(entries: ArchiveEntry[]): string[] {
    const names: string[] = [];
    for (const entry of entries) {
        if (entry.active) {
            names.push(entry.name);
        }
    }
    return names;
}

function groupBy<T>(
    items: T[],
    keyOf: (item: T) => string
): Record<string, T[]> {
    const groups: Record<string, T[]> = {};
    for (const item of items) {
        const key = keyOf(item);
        if (!groups[key]) {
            groups[key] = [];
        }
        groups[key].push(item);
    }
    return groups;
}

