fn summarize(values: &[i32]) -> i32 {
    let mut total = 0;
    for &value in values {
        if value > 0 {
            total += value;
        }
    }
    total
}

fn main() {
    let numbers = [3, -1, 7, 0, 4];
    println!("{}", summarize(&numbers));
}

fn find_index(items: &[&str], target: &str) -> Option<usize> {
    for (index, item) in items.iter().enumerate() {
        if *item == target {
            return Some(index);
        }
    }
    None
}

fn main() {
    let names = ["signal", "archive", "relay"];
    println!("{:?}", find_index(&names, "relay"));
}

fn format_station(name: &str, strength: u32) -> String {
    if strength == 0 {
        return format!("{}: offline", name);
    }
    format!("{}: {} percent", name, strength)
}

fn main() {
    let stations = [("north", 72), ("south", 0)];
    for (name, strength) in stations {
        println!("{}", format_station(name, strength));
    }
}
